import {ARCHITECTURES,PARITY_POSITIONS,DATA_POSITIONS,PATTERNS,encode64,hexToBits,inspectLab} from './fault-lab.js';

export function labPage(lab,campaign,ui) {
  const {card,btn,badge,table,fmt,h,notice,metric}=ui;
  const outcomes=inspectLab(lab),current=outcomes[lab.view],golden=hexToBits(lab.hex),encoded=encode64(golden);
  const statuses={correct:['정상 데이터 확보','green'],detected:['검출 · 출력 사용 중단','amber'],silent:['미검출 데이터 손상','red']};
  const stateBadge=o=>badge(...statuses[o.status]);
  function bitGrid(bank,values,reference,copy=0) {
    return `<div class="bit-grid" role="group" aria-label="${bank==='tmr'?'복제본 '+['A','B','C'][copy]:ARCHITECTURES[bank]} 비트 조작">${values.map((b,i)=>{
      const parity=bank==='ecc'&&(PARITY_POSITIONS.includes(i+1)||i===71);
      const label=bank==='ecc'?(i===71?'P전체':parity?'P'+(i+1):'D'+DATA_POSITIONS.indexOf(i+1)):'D'+i;
      const changed=b!==reference[i];
      return `<button type="button" class="bit ${parity?'parity':''} ${changed?'flipped':''}" data-lab-bit="${i}" data-bank="${bank}" data-copy="${copy}" aria-label="${bank==='tmr'?'복제본 '+['A','B','C'][copy]+' ':''}${label}, 현재 ${b}, ${changed?'초기값과 다름':'초기값과 같음'}, 누르면 반전" aria-pressed="${changed}"><span>${label}</span><b>${b}</b></button>`;
    }).join('')}</div>`;
  }
  const memory=lab.view==='tmr'?lab.tmr.map((a,i)=>`<div class="replica-head">복제본 ${['A','B','C'][i]} <span>64 bit</span></div>${bitGrid('tmr',a,golden,i)}`).join(''):bitGrid(lab.view,lab[lab.view],lab.view==='ecc'?encoded:golden);
  const circuitFlag=lab.view==='ecc'?{clean:'오류 신호 없음',corrected:`${current.correctedPosition}번 비트 정정`,uncorrectable:'정정 불가 신호'}[current.flag]:lab.view==='tmr'?`복제본 불일치 ${current.disagreementBits}개 비트`:'오류 검출 신호 없음';
  const comparison=Object.entries(outcomes).map(([k,o])=>`<tr class="${k===lab.view?'selected':''}"><td>${h(ARCHITECTURES[k])}</td><td class="number">${o.physicalBits}</td><td>${stateBadge(o)}</td><td class="number">${o.mismatch}</td></tr>`);
  const campaignRows=campaign?Object.entries(campaign.counts).map(([key,c])=>`<tr><td>${h(ARCHITECTURES[key])}</td><td class="number">${fmt(c.correct,0)}</td><td class="number">${fmt(c.detected,0)}</td><td class="number">${fmt(c.silent,0)}</td><td class="number">${fmt(c.correct/campaign.trials*100)}%</td></tr>`):[];
  const campaignBars=campaign?Object.entries(campaign.counts).map(([key,c])=>`<div class="campaign-bar-row"><strong>${h(ARCHITECTURES[key])}</strong><div class="campaign-bar" role="img" aria-label="${h(ARCHITECTURES[key])}, 정상 ${c.correct}, 검출 ${c.detected}, 미검출 손상 ${c.silent}">${['correct','detected','silent'].map(k=>`<span class="${k}" style="width:${c[k]/campaign.trials*100}%"></span>`).join('')}</div></div>`).join(''):'';
  return `${notice('<strong>비트 단위 설계 실험</strong> 지정한 오류에 대한 회로의 동작을 계산합니다. 궤도별 방사선 발생률은 분석 대시보드에서 별도로 비교하세요.','info')}
    <div class="lab-toolbar card"><div class="lab-data-field"><label for="lab-hex">기준 데이터 · 64 bit / 16진수</label><form id="lab-data-form"><input id="lab-hex" name="hex" value="${h(lab.hex)}" maxlength="16" pattern="[0-9a-fA-F]{16}" required spellcheck="false" autocomplete="off"><button class="btn" type="submit">기록</button></form></div><div class="lab-presets"><span class="small text-muted">오류 예시 · 각 예시는 초기값에서 시작</span><div class="button-row">${btn('1-bit','lab-single')}${btn('한 복제본 2-bit','lab-double')}${btn('두 복제본 동시','lab-common')}${btn('3-bit 취약 사례','lab-triple')}</div></div></div>
    <div class="lab-workspace">
      ${card('메모리 비트를 눌러 오류 주입',`<div class="card-body"><div class="segmented lab-modes" aria-label="설계 구조 선택">${Object.entries(ARCHITECTURES).map(([key,name])=>`<button type="button" data-lab-view="${key}" class="${lab.view===key?'active':''}" aria-pressed="${lab.view===key}">${h(name)}</button>`).join('')}</div><div class="bit-legend"><span>데이터</span><span class="legend-parity">검사 비트</span><span class="legend-flipped">초기값과 다른 비트</span></div>${memory}<div class="button-row spaced"><button type="button" class="btn primary" data-action="lab-scrub" ${lab.view==='raw'?'disabled':''}>${lab.view==='tmr'?'다수결로 재동기화':'정정값으로 스크러빙'}</button>${btn('전체 초기화','lab-clear')}</div><p class="input-note">D0는 최하위 비트입니다. 읽기 결과는 즉시 계산되며, 스크러빙을 눌러야 저장 비트가 바뀝니다. 원본 기준값은 결과 채점에만 사용합니다.</p></div>`)}
      <section class="lab-readout" aria-live="polite" aria-label="실시간 읽기 결과"><p class="eyebrow">READOUT / ${h(lab.view.toUpperCase())}</p><h2>읽기 결과</h2><div class="readout-status">${stateBadge(current)}</div><label>기준 데이터</label><p class="hex-value">${h(lab.hex)}</p><label>회로 계산 데이터</label><p class="hex-value ${current.mismatch?'damaged':''}">${h(current.hex)}</p><div class="readout-line"><span>회로가 내보낸 신호</span><strong>${h(circuitFlag)}</strong></div><div class="readout-line"><span>원본과 다른 데이터</span><strong>${current.mismatch} / 64 bit</strong></div>${lab.view==='ecc'?`<div class="readout-line"><span>신드롬 / 전체 홀수 패리티</span><strong>${current.syndrome} / ${current.odd}</strong></div>`:''}<p class="readout-note">‘미검출 손상’은 원본을 아는 실험기가 확인한 결과입니다. 실제 회로는 원본과 비교할 수 없습니다.${lab.view==='tmr'?' 잘못된 다수결 값을 재동기화하면 손상이 세 복제본으로 전파됩니다.':''}${current.status==='detected'?' 표시된 데이터는 사용을 중단하고 상위 시스템에서 복구해야 합니다.':''}</p></section>
    </div>
    <div class="spaced">${card('같은 기준 데이터, 세 가지 보호 구조',table(['설계','저장 비트','읽기 판정','원본 대비 오류 bit'],comparison,'1-bit 예시는 A 복제본에만 주입합니다. 2-bit 예시는 A의 D0·D1, 두 복제본 동시는 A·B의 D0, 3-bit 예시는 A·B·C의 D0를 반전합니다. 보호 없음·ECC에는 각각 D0부터 1·2·3개 데이터 비트를 반전합니다.'))}</div>
    <div class="grid-equal">
      ${card('반복 오류 주입 실험',`<div class="card-body"><div class="field-grid"><label class="full"><span>오류 패턴</span><select data-lab-config="pattern">${Object.entries(PATTERNS).map(([key,value])=>`<option value="${key}" ${lab.pattern===key?'selected':''}>${h(value)}</option>`).join('')}</select></label><label><span>반복 횟수</span><input type="number" data-lab-config="trials" min="1" max="20000" step="1" value="${lab.trials}"></label><label><span>난수 시드</span><input type="number" data-lab-config="seed" min="0" max="4294967295" step="1" value="${lab.seed}"></label></div><div class="button-row spaced">${btn('반복 실험 실행','lab-run','arrow','primary')}${campaign?btn('실험 결과 CSV','lab-csv','download'):''}</div><p class="input-note">매 시행마다 정상 상태에서 시작해 구조별 동일 개수의 서로 다른 물리 비트를 반전합니다. 시드·입력이 같으면 결과를 재현할 수 있습니다. 위의 수동 주입 상태는 사용하지 않습니다.</p></div>`)}
      ${card('오류 정정과 저장공간',`<div class="card-body explain"><p><strong>SECDED:</strong> 데이터 64 bit + 검사 8 bit. 모든 단일 비트 오류를 정정하고 모든 이중 비트 오류를 검출하는 확장 해밍 부호입니다. 3-bit 이상에서는 오정정·미검출이 가능합니다.</p><p><strong>TMR:</strong> 데이터 64 bit × 3 복제본. 각 비트의 다수결과 복제본 불일치 신호를 계산합니다. 투표기·클록·리셋 자체 고장은 포함하지 않습니다.</p><p><strong>공간 오버헤드:</strong> SECDED 12.5%, TMR 200%. 저장 비트 수의 증가이며 전체 칩 면적·전력 증가율이 아닙니다.</p><p><a href="https://ntrs.nasa.gov/citations/20180006778" target="_blank" rel="noopener noreferrer">NASA · FPGA 보호설계 참고자료 ↗</a></p></div>`)}
    </div>
    <div class="spaced">${card('반복 실험 결과',campaign?`<div class="card-body"><div class="pill-row">${badge(PATTERNS[campaign.pattern],'blue')}${badge(fmt(campaign.trials,0)+'회')}${badge('시드 '+campaign.seed)}${badge(campaign.hex)}</div><div class="campaign-legend"><span class="correct">정상 데이터</span><span class="detected">검출·중단 필요</span><span class="silent">미검출 손상</span></div>${campaignBars}</div>${table(['설계','정상 데이터','검출·중단 필요','미검출 손상','정상 데이터 비율'],campaignRows)}<p class="table-note">이 값은 선택한 오류 패턴을 주입했을 때의 결과입니다. 동일한 방사선 노출에 대한 발생확률이나 위성 신뢰도가 아닙니다. 독립 패턴은 전체 물리 비트에서 균등 추출하며, 상관 패턴은 TMR 두 복제본의 같은 비트에 주입합니다. 보호 없음·ECC의 상관 패턴은 서로 다른 2-bit 주입입니다. 현재 실험은 시행 사이 시간·스크러빙 주기를 모델링하지 않습니다.</p>`:'<div class="empty"><strong>오류 패턴을 고르고 실험을 실행하세요</strong>정상 데이터 확보, 검출된 손상, 미검출 손상을 구분해 비교합니다.</div>')}</div>
    <div class="spaced">${card('K-LEO 설계 검토에 연결',`<div class="card-body explain"><p>이 실험으로 정정·검출·복구 동작을 확인한 뒤, 목표궤도의 부품별 오류율과 보호·복구 설계 가정을 함께 검토하세요. 반복 실험의 정상 데이터 비율을 궤도 오류율에 직접 곱하지 않습니다. 실제 오류 위치의 상관관계와 동작조건이 다를 수 있습니다.</p><div class="button-row spaced">${btn('궤도·부품 비교','go-overview','arrow')}${btn('보호·복구율 검토','go-protection','shield')}${btn('검증계획','go-verification','check')}</div></div>`)}</div>`;
}
